code_example:
namespace System {
    namespace Internal {
        int resource_count = 0;
    }
    void cleanup() {
        Internal::resource_count = 0;
    }
}

namespace Application {
    // Fully Qualified Name Lookup required.
    // 1. System resolved from global/enclosing scope.
    // 2. Internal resolved from System scope.
    void use_resource() {
        System::Internal::resource_count++;
    }
}

// Global scope access uses ::
void global_access() {
    ::System::Internal::resource_count = 10;
}
